function calculateSodaCost() {
  const dailyBottles = parseFloat(document.getElementById('dailyBottles').value) || 0;
  const petPrice = parseFloat(document.getElementById('petPrice').value) || 0;
  const makerCost = parseFloat(document.getElementById('makerCost').value) || 0;
  const gasCost = parseFloat(document.getElementById('gasCost').value) || 0;
  const fizzFactor = parseFloat(document.getElementById('fizzLevel').value) || 1;
  const waterCostPerL = parseFloat(document.getElementById('waterCostPerL').value) || 0;

  // 1本のガス(基準60L)から作れる実質L数
  const actualLitersPerGas = 60 / fizzFactor;
  // 500ml換算で作れる本数
  const actualBottlesPerGas = actualLitersPerGas * 2;
  // 炭酸水メーカーで作る500mlあたりの単価 (ガス代 + 水代0.5L分)
  const maker500mlCost = (gasCost / actualBottlesPerGas) + (waterCostPerL * 0.5);

  // 500ml 1本あたりの差額
  const diffPerBottle = petPrice - maker500mlCost;

  // 年間本数
  const annualBottles = dailyBottles * 365;
  // 年間のランニングコスト差額
  const annualSavings = diffPerBottle * annualBottles;

  // 損益分岐点（元が取れるまでの日数）
  let breakEvenDays = 0;
  let breakEvenText = '';
  if (diffPerBottle <= 0) {
    breakEvenText = '元は取れません（ペットボトルのほうが割安）';
  } else {
    const dailySavings = diffPerBottle * dailyBottles;
    breakEvenDays = Math.ceil(makerCost / dailySavings);
    const months = (breakEvenDays / 30.4).toFixed(1);
    breakEvenText = `${breakEvenDays}日（約${months}ヶ月）で回収`;
  }

  // 3年間の実質トータル節約額 (年間節約額 * 3 - 本体代)
  const threeYearNetSavings = Math.round((annualSavings * 3) - makerCost);

  const resultDiv = document.getElementById('calcResult');
  if (!resultDiv) return;

  if (diffPerBottle <= 0) {
    resultDiv.innerHTML = `
      <div class="result-headline">結論：<strong>現在の設定ではペットボトルのほうが安価です</strong></div>
      <div class="metrics-row">
        <div class="metric-card"><span>ペットボトル500ml</span><strong>${petPrice.toFixed(1)}円</strong><small>購入単価</small></div>
        <div class="metric-card"><span>メーカー製500ml</span><strong>${maker500mlCost.toFixed(1)}円</strong><small>ガス＋水代</small></div>
      </div>
    `;
    return;
  }

  resultDiv.innerHTML = `
    <div class="result-headline">結論：<strong>約${Math.ceil(breakEvenDays / 30.4)}ヶ月で本体代を回収！年間【約${Math.round(annualSavings).toLocaleString()}円】の節約</strong></div>
    <div class="metrics-row">
      <div class="metric-card">
        <span>500mlあたりの単価</span>
        <strong>${maker500mlCost.toFixed(1)}円</strong>
        <small>ペットボトル比 -${diffPerBottle.toFixed(1)}円</small>
      </div>
      <div class="metric-card">
        <span>元が取れる損益分岐点</span>
        <strong>${breakEvenDays}日</strong>
        <small>約${(breakEvenDays / 30.4).toFixed(1)}ヶ月で本体代償却</small>
      </div>
      <div class="metric-card">
        <span>年間のランニング節約額</span>
        <strong>${Math.round(annualSavings).toLocaleString()}円</strong>
        <small>1日${dailyBottles}本（年間${annualBottles}本）消費時</small>
      </div>
      <div class="metric-card">
        <span>3年間の純トータル節約額</span>
        <strong>${threeYearNetSavings.toLocaleString()}円</strong>
        <small>本体購入費を差し引いた純利益</small>
      </div>
    </div>
  `;
}

document.addEventListener('DOMContentLoaded', calculateSodaCost);
